#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int INF = 10000000;

    int n;
    cin >> n;
    string seq_str;
    cin >> seq_str;
    vector<char> sequence(n);
    for (int i = 0; i < n; i++) {
        sequence[i] = seq_str[i];
    }

    int vCount = 0, kCount = 0, xCount = 0;
    for (int i = 0; i < n; i++) {
        if (sequence[i] == 'V') vCount++;
        else if (sequence[i] == 'K') kCount++;
        else {
            sequence[i] = 'X';
            xCount++;
        }
    }

    vector<vector<vector<vector<int>>>> dpTable(
        vCount + 1,
        vector<vector<vector<int>>>(
            kCount + 1,
            vector<vector<int>>(
                xCount + 1,
                vector<int>(3, INF)
            )
        )
    );

    for (int i = 0; i < 3; i++) {
        dpTable[0][0][0][i] = 0;
    }

    auto countChars = [&](const vector<char>& arr, char target, int v, int k, int x) {
        int cost = 0;
        for (char c : arr) {
            if (c == 'V') {
                v--;
                if (v == 0 && target == 'V') return cost;
                if (v < 0) cost++;
            }
            if (c == 'K') {
                k--;
                if (k == 0 && target == 'K') return cost;
                if (k < 0) cost++;
            }
            if (c == 'X') {
                x--;
                if (x == 0 && target == 'X') return cost;
                if (x < 0) cost++;
            }
        }
        throw runtime_error("Invalid state");
    };

    for (int v = 0; v <= vCount; v++) {
        for (int k = 0; k <= kCount; k++) {
            for (int x = 0; x <= xCount; x++) {
                for (int prevState = 0; prevState < 3; prevState++) {
                    int currentCost = dpTable[v][k][x][prevState];
                    if (currentCost == INF) continue;
                    if (v + 1 <= vCount) {
                        int costV = countChars(sequence, 'V', v + 1, k, x);
                        dpTable[v + 1][k][x][0] = min(dpTable[v + 1][k][x][0], currentCost + costV);
                    }
                    if (k + 1 <= kCount) {
                        int costK = countChars(sequence, 'K', v, k + 1, x);
                        if (prevState != 0) {
                            dpTable[v][k + 1][x][1] = min(dpTable[v][k + 1][x][1], currentCost + costK);
                        }
                    }
                    if (x + 1 <= xCount) {
                        int costX = countChars(sequence, 'X', v, k, x + 1);
                        dpTable[v][k][x + 1][2] = min(dpTable[v][k][x + 1][x + 1][2], currentCost + costX);
                    }
                }
            }
        }
    }

    int answer = INF;
    for (int i = 0; i < 3; i++) {
        answer = min(answer, dpTable[vCount][kCount][xCount][i]);
    }
    cout << answer << "\n";

    return 0;
}

